def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers. Later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends: {"plugins+": ["x"]} appends items to base list "plugins".
      If base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs must not be mutated, and the result must not share mutable dicts/lists with inputs (deep copy).
    """
    import copy

    def _deep_copy(value):
        """Deep copy a value, handling dicts and lists."""
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deep_copy(item) for item in value]
        else:
            return value

    def _merge_two(base_dict, override_dict):
        """
        Merge two dicts. Returns a new dict.
        - Dicts merged recursively
        - None in override deletes key
        - Keys ending in '+' append to list
        - Other values replace
        """
        result = _deep_copy(base_dict)

        for key, value in override_dict.items():
            if key.endswith('+'):
                # Append mode
                base_key = key[:-1]
                if base_key in result:
                    existing = result[base_key]
                    if not isinstance(existing, list):
                        raise TypeError(f"Cannot append to non-list value for key '{base_key}'")
                    # Append deep-copied items
                    if isinstance(value, list):
                        result[base_key] = existing + _deep_copy(value)
                    else:
                        # If value is not a list, treat as single item to append
                        result[base_key] = existing + [_deep_copy(value)]
                else:
                    # Base key doesn't exist, create new list
                    if isinstance(value, list):
                        result[base_key] = _deep_copy(value)
                    else:
                        result[base_key] = [_deep_copy(value)]
            elif value is None:
                # Delete key from result
                if key in result:
                    del result[key]
            elif isinstance(value, dict) and key in result and isinstance(result[key], dict):
                # Recursive merge for dicts
                result[key] = _merge_two(result[key], value)
            else:
                # Replace with deep copy
                result[key] = _deep_copy(value)

        return result

    # Start with a deep copy of base
    result = _deep_copy(base)

    # Apply each override in order
    for override in overrides:
        result = _merge_two(result, override)

    return result
