def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty input")

    # Check for invalid characters (only digits, spaces, and unit letters allowed)
    allowed_chars = set("0123456789 dDhHmMsS")
    for ch in s:
        if ch not in allowed_chars:
            raise ValueError(f"Invalid character: {ch}")

    # Split by spaces and validate single spaces only
    parts = s.split(" ")
    # Check for empty parts (which would indicate multiple spaces or leading/trailing spaces)
    for part in parts:
        if part == "":
            raise ValueError("Invalid spacing")

    # Define units and their order
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = ['d', 'h', 'm', 's']

    last_unit_index = -1
    total_seconds = 0

    for part in parts:
        # Parse each part: must be <integer><unit>
        if not part:
            raise ValueError("Empty part")

        # Find where the number ends and unit begins
        num_end = 0
        while num_end < len(part) and part[num_end].isdigit():
            num_end += 1

        if num_end == 0:
            raise ValueError("Missing number")
        if num_end == len(part):
            raise ValueError("Missing unit")

        # The rest should be exactly one character (the unit)
        if len(part) - num_end != 1:
            raise ValueError("Invalid part format")

        number = int(part[:num_end])
        unit_char = part[num_end].lower()

        if unit_char not in units:
            raise ValueError(f"Unknown unit: {unit_char}")

        # Check order
        current_unit_index = unit_order.index(unit_char)
        if current_unit_index <= last_unit_index:
            raise ValueError("Wrong order or repeated unit")
        last_unit_index = current_unit_index

        total_seconds += number * units[unit_char]

    return total_seconds


def format_duration(seconds: int) -> str:
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    days = seconds // 86400
    seconds %= 86400
    hours = seconds // 3600
    seconds %= 3600
    minutes = seconds // 60
    seconds %= 60

    parts = []
    if days > 0:
        parts.append(f"{days}d")
    if hours > 0:
        parts.append(f"{hours}h")
    if minutes > 0:
        parts.append(f"{minutes}m")
    if seconds > 0:
        parts.append(f"{seconds}s")

    return "".join(parts)
