def flatten(obj, sep="."):
    """
    Flatten a nested dict/list structure into a flat dict with path keys.

    Args:
        obj: The object to flatten. Must be a dict.
        sep: Separator for path keys. Default is "."

    Returns:
        A flat dict with path keys.

    Raises:
        TypeError: If obj is not a dict.
        ValueError: If a key contains the separator.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path):
        if isinstance(current, dict):
            if not current:
                # Empty dict is a leaf
                result[path] = current
                return
            for key, value in current.items():
                if not isinstance(key, str):
                    raise ValueError("Keys must be strings")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")
                new_path = f"{path}{sep}{key}" if path else key
                _flatten(value, new_path)
        elif isinstance(current, list):
            if not current:
                # Empty list is a leaf
                result[path] = current
                return
            for i, value in enumerate(current):
                new_path = f"{path}{sep}{i}"
                _flatten(value, new_path)
        else:
            # Leaf value
            result[path] = current

    _flatten(obj, "")
    return result


def unflatten(flat, sep="."):
    """
    Unflatten a flat dict with path keys back into a nested dict/list structure.

    Args:
        flat: The flat dict to unflatten.
        sep: Separator for path keys. Default is "."

    Returns:
        A nested dict/list structure.

    Raises:
        ValueError: If there are conflicts or invalid list indices.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Parse all paths
    paths = []
    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("Keys must be strings")
        parts = key.split(sep)
        paths.append((parts, value))

    # Build a tree structure
    # Each node is a dict with:
    #   - 'children': dict mapping child keys to child nodes
    #   - 'value': the leaf value if this is a leaf
    #   - 'is_leaf': whether this node is a leaf

    root = {'children': {}, 'value': None, 'is_leaf': False}

    for parts, value in paths:
        node = root
        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)

            if part not in node['children']:
                node['children'][part] = {'children': {}, 'value': None, 'is_leaf': False}

            node = node['children'][part]

            if is_last:
                if node['is_leaf'] or node['children']:
                    raise ValueError(f"Conflict at path: {sep.join(parts)}")
                node['is_leaf'] = True
                node['value'] = value

    # Convert the tree to the final structure
    def _convert(node):
        if node['is_leaf']:
            return node['value']

        # Determine if this node is a list or dict
        # Check if all children keys are valid list indices
        all_list_indices = True
        for key in node['children']:
            if not _is_valid_list_index(key):
                all_list_indices = False
                break

        if all_list_indices and node['children']:
            # This is a list
            indices = [int(k) for k in node['children']]
            n = len(indices)
            expected = set(range(n))
            actual = set(indices)
            if actual != expected:
                raise ValueError(f"List indices must be dense: expected {sorted(expected)}, got {sorted(actual)}")
            result = []
            for i in range(n):
                result.append(_convert(node['children'][str(i)]))
            return result
        else:
            # This is a dict
            result = {}
            for key, child in node['children'].items():
                result[key] = _convert(child)
            return result

    def _is_valid_list_index(key):
        """Check if a key is a valid list index (non-negative integer without leading zeros)."""
        if not isinstance(key, str):
            return False
        if not key.isdigit():
            return False
        if key == "0":
            return True
        if key[0] == '0':
            return False
        return True

    return _convert(root)
